'use strict';
(()=>{
 const SCENES=Object.freeze({forest:{image:'scout-forest.webp',short:'Mroczny Las'},mine:{image:'scout-mine.webp',short:'Stara Kopalnia'},undercity:{image:'scout-undercity.webp',short:'Podziemia Miasta'},archive:{image:'severin-archive.webp',short:'Archiwum Pieczęci'},throne:{image:'castle-throne-queen.webp',short:'Sala tronowa'},vespera:{image:'vespera-bedroom.webp',short:'Sypialnia Vespery'},ubocze:{image:'golden-pony-interior.webp',short:'Ubocze · Pod Złotym Kucem'},eldor:{image:'scout-forest.webp',short:'Eldor · Leśna pieczęć'},ice:{image:'glade-ice-hills-icon.webp',short:'Lodowe Wzgórza'},hell:{image:'hell-gates-camp-map.webp',short:'Wrota Piekieł'}});
 const main=[
  ['uninvited','Nieproszeni goście',5,'Tauriel','tavern',['tauriel'],'Na piętrze karczmy zabarykadowali się rozbójnicy. Tauriel zauważyła na ich liście przewozowym królewski znak. Przepędź napastników i zakończ jej zadanie, aby zdobyć pierwszy trop.','Tauriel przekazuje Ci odbitkę pieczęci znalezioną przy barykadzie. Ktoś korzysta z królewskich szlaków, nie mając prawa do królewskiej ochrony.',80,500],
  ['iron-oath','Żelazna Przysięga',10,'Gabriel','training',['gabriel'],'Gabriel rozpoznaje na dokumencie trasę skradzionego uzbrojenia. Ukończ jego szkolenie i odzyskaj broń, tarczę oraz hełm. Zamek musi wiedzieć, komu może zaufać.','Gabriel potwierdza Twoją przysięgę. W skrzyniach po broni znaleziono trzy rozkazy: do lasu, kopalni i miejskich podziemi.',100,1500],
  ['three-reports','Trzy niepokojące raporty',10,'Brand','journal',['report-forest','report-mine','report-undercity'],'Zbierz raporty z Mrocznego Lasu, Starej Kopalni i Podziemi Miasta. Wcześniej rozliczone wyprawy z tych terenów również są dowodem; brakujące raporty możesz zdobyć podczas wypraw fabularnych.','W każdym raporcie powtarza się znak siedmiu pierścieni. Wszystkie transporty dopuszczono tym samym królewskim stemplem.',150,3500],
  ['root-whisper','Szept spod korzeni',12,'Lyrien','journal',['win:root-warden','root-memory'],'Pod leśnymi korzeniami budzi się strażnik starej przysięgi. Ucisz jego gniew i zbadaj kamień, którego pęknięcie nie powstało od upływu czasu.','Kamień pamięta dłoń urzędnika w rękawicy. Korzenie wskazują ku starej kopalni, gdzie przerwano kolejną pieczęć.',200,7000],
  ['miners-shift','Ostatnia zmiana górników',15,'Brand','journal',['win:foreman-echo','mine-ledger'],'Ostatnia zmiana nigdy nie wróciła na powierzchnię. Przedrzyj się przez echo sztygara i zabezpiecz księgę odpraw. Ustal, kto wysłał górników do zamkniętego chodnika.','Odprawa nosi świeży odcisk królewskiego stempla. Do księgi przywiązano kość z nazwiskiem jednego z górników.',250,10000],
  ['bone-memory','Pamięć zamknięta w kości',15,'Severin','archive',['boss:1','bone-remembrance'],'Pokonaj pierwszego bossa Cmentarzyska, jeśli nie masz już tego zwycięstwa za sobą. Następnie odwiedź Archiwum Pieczęci i odczytaj pamięć kości wraz z Mistrzem Pieczęci.','Wspomnienie odsłania zasypane przejście spod kopalni na Cmentarzysko. Severin twierdzi, że odcisk w księdze musiał zostać podrobiony.',250,12000],
  ['sleepless-graves','Cmentarz bez snu',20,'Gabriel','dungeon',['boss:5','grave-register'],'Doprowadź wyprawę na Cmentarzysko do końca. Upiór, Szkielet, Licz, Czarny Rycerz i Minotaur strzegą jednej drogi. Zapisane wcześniej zwycięstwa pozostają zaliczone.','Rejestr pochówków ujawnia zaginionych górników. Wśród ich rzeczy jest ostrze nacięte znakiem siódmej pieczęci.',500,25000,2],
  ['blade-trace','Ślad na ostrzu',22,'Kowal Czarnego Żaru','journal',['blade-imprint','win:seal-courier'],'Porównaj nacięcie ostrza z dokumentami transportowymi. Następnie przechwyć kuriera w miejskich podziemiach, zanim zniszczy oryginały rozkazów.','List kuriera nosi tę samą wadę stempla co królewskie dokumenty. To nie kopia pieczęci: ktoś z zamku używa oryginału.',600,30000],
  ['masked-face','Twarz pod maską',25,'Archiwum Pieczęci','archive',['seal-comparison','unmasked'],'Wróć do Archiwum Pieczęci. Zestaw dokument Tauriel, księgę górników i list kuriera z urzędowym wzorcem. Dopiero komplet dowodów pozwoli nazwać zdrajcę.','Ślad pękniętego pierścienia pasuje wyłącznie do osobistego stempla Severina. Mistrz Pieczęci przyznaje, że odwrócił ochronne znaki zamku. To on złamał przysięgę.',750,35000],
  ['broken-crown','Noc Pękniętej Korony',25,'Królowa','throne',['crown-warning','win:severin-oath'],'Ostrzeż królową w sali tronowej, zanim zabrzmi ostatni dzwon. Następnie powstrzymaj Severina w Archiwum Pieczęci i przerwij rytuał Pękniętej Korony.','Rytuał zostaje przerwany, a Severin trafia pod straż. Zamek ocalał, lecz cztery odległe pieczęcie nadal pękają. Ich ślad prowadzi przez Ubocze, Eldor, Lodowe Wzgórza aż do Wrót Piekieł.',1000,50000,5]
 ];
 const side=[
  ['trophies','Trofea i wspomnienia',10,'Tauriel','tavern',['trophies:3','trophy-memories'],'iron-oath','Tauriel prosi o wspomnienia z trzech zwycięstw. Spisane opowieści mają pomóc rodzinom rozpoznać tych, którzy nie wrócili. Dotychczasowe walki również się liczą.','Opowieści otrzymują imiona. Tauriel zapisuje je w księdze gości, zamiast pozwolić, by zniknęły w kolejnej wojennej plotce.',120,2500,1],
  ['ownerless-cargo','Towar bez właściciela',12,'Brand','journal',['ownerless-crate'],'three-reports','W kopalni pozostała skrzynia z zaopatrzeniem, na którą nikt nie wystawił rachunku. Sprawdź znak przewozowy i zdecyduj, komu przekażesz zapasy.','Skrzynia nie wraca na czarny rynek. Zostaje tam, gdzie Twoim zdaniem przyniesie najwięcej dobra.',180,4000],
  ['lost-mirror','Zaginione lustro',15,'Vespera','vespera-bedroom',['win:mirror-shadow','mirror-return'],'miners-shift','Zniknęło stare lustro Vespery. Odbicie uciekło do lasu i nie pozwala nikomu podejść. Uwolnij lustro, a potem odwiedź sypialnię Vespery, by oddać jej zgubę.','Lustro wraca do sypialni. Vespera zauważa, że przez chwilę odbijało siedem pierścieni zamiast jednej twarzy.',220,6000,2],
  ['fallen-names','Imiona poległych',20,'Gabriel','archive',['boss:5','fallen-memorial'],'sleepless-graves','Ocalone rejestry pozwalają przywrócić nazwiska zmarłym z Cmentarzyska. Odwiedź archiwum i połącz listę górników z księgą poległych.','Gabriel otrzymuje pełną listę. Przy murze zamku zostaje odczytane każde imię — żaden z poległych nie pozostaje numerem.',300,10000,2]
 ];
 const chapters=[
  ['outskirts-seal','Ubocze — Popiół na trakcie',30,'Pod Złotym Kucem','ubocze',['visit:ubocze','outskirts-witness','win:outskirts-warden'],'broken-crown','W karczmie „Pod Złotym Kucem” czeka świadek kolejnego transportu. Zbierz jego zeznanie i odzyskaj pierwszą z odwróconych pieczęci na leśnym trakcie.','Pieczęć Ubocza znów chroni drogę. Znak na jej odwrocie wskazuje ku elfickiemu Eldorowi.',2000,200000,3],
  ['eldor-seal','Eldor — Pieśń złamanej pieczęci',50,'Strażnicy Eldoru','eldor',['visit:eldor','eldor-song','win:eldor-warden'],'outskirts-seal','W Eldorze zamilkła pieśń ochronna. Odczytaj świadectwo strażników i uwolnij zniekształconego opiekuna korzeni.','Eldor odzyskuje swój głos. Pęknięcie prowadzi dalej, ku sercu pieczęci ukrytej w lodzie.',4000,3000000,5],
  ['ice-seal','Lodowe Wzgórza — Serce pod lodem',75,'Kronikarz krasnoludów','ice-hills',['visit:ice-hills','ice-runes','win:ice-warden'],'eldor-seal','Krasnoludzkie runy chroni lód starszy od zamku. Odczytaj je i powstrzymaj strażnika, którego Severin związał odwróconą przysięgą.','Lód przestaje pękać. Ostatnia runa wskazuje Wrota Piekieł — miejsce, do którego miały odpłynąć moce wszystkich pieczęci.',7000,30000000,7],
  ['hell-seal','Wrota Piekieł — Ostatnia pieczęć',110,'Obóz najemników','hell-gates',['visit:hell-gates','hell-anchor','win:hell-warden'],'ice-seal','Przejdź przez Ubocze do Wrót Piekieł. Zlokalizuj kotwicę rytuału i powstrzymaj strażnika, zanim otworzy przejście pod Zamkiem Czarnej Stali.','Ostatnia pieczęć zamyka drogę ciemności. Pęknięta Przysięga zostaje naprawiona czynami, a nie obietnicą Severina.',12000,600000000,10]
 ];
 const CATALOG=Object.freeze([
  ...main.map(([id,title,level,giver,destination,goals,story,ending,gold,xp,shards=0],i)=>({id,title,level,giver,destination,goals,story,ending,reward:{gold,xp,shards},kind:'main',requires:i?[main[i-1][0]]:[]})),
  ...side.map(([id,title,level,giver,destination,goals,previous,story,ending,gold,xp,shards=0])=>({id,title,level,giver,destination,goals,story,ending,reward:{gold,xp,shards},kind:'side',requires:[previous]})),
  ...chapters.map(([id,title,level,giver,destination,goals,previous,story,ending,gold,xp,shards=0])=>({id,title,level,giver,destination,goals,story,ending,reward:{gold,xp,shards},kind:'chapter',requires:[previous]}))
 ].map(q=>Object.freeze({...q,reward:Object.freeze(q.reward),goals:Object.freeze(q.goals),requires:Object.freeze(q.requires)})));
 const acts=[];
 function inspect(id,quest,title,scene,text,choices,options={}){acts.push({id,quest,title,scene,text,choices:choices.map(([id,label,result])=>({id,label,result})),kind:'inspect',requires:[],...options});}
 function fight(id,quest,title,scene,level,hp,damage,options={}){const {enemy,...rest}=options;acts.push({id,quest,title,scene,kind:'fight',requires:[],enemy:{id:'oath-'+id,name:title,level,maxHp:hp,stats:[level,Math.max(5,Math.floor(level*.6)),Math.max(5,Math.floor(level*.5)),level],attack:damage,atlas:'graveyard',tile:3,...enemy},...rest});}
 inspect('report-forest','three-reports','Raport z Mrocznego Lasu','forest','Na mokrej ziemi widać ślady wozu i odłamki zielonego wosku. Woźnica ominął strażnicę, pokazując glejt z siedmioma pierścieniami.',[['record','Zabezpiecz wosk i odrysuj ślady','Raport leśny: transport przejechał pod osłoną królewskiego glejtu.']]);
 inspect('report-mine','three-reports','Raport ze Starej Kopalni','mine','W opuszczonej wartowni znajdujesz rozkaz zdjęcia straży z zamkniętego chodnika. Podpis zatarto, lecz pieczęć pozostawiono nienaruszoną.',[['record','Skopiuj rozkaz i pieczęć','Raport z kopalni: ktoś świadomie otworzył niebezpieczny chodnik.']]);
 inspect('report-undercity','three-reports','Raport z Podziemi Miasta','undercity','Pod zamkiem świeży transport zniknął za kratą. W książce wart wpisano tę samą godzinę, o której z kopalni zniknęła ostatnia zmiana.',[['record','Zapisz godzinę i trasę transportu','Raport z podziemi: wszystkie trzy zdarzenia łączy jeden rozkaz.']]);
 fight('root-warden','root-whisper','Strażnik Spękanych Korzeni','forest',12,165,[9,13]);
 inspect('root-memory','root-whisper','Odczytaj szept korzeni','forest','Za pokonanym strażnikiem kamień odsłania świeże nacięcie. Korzenie powtarzają słowa: „Nie otwieraj siódmego kręgu”.',[['listen','Wysłuchaj korzeni i przerysuj znak','Ocalał odcisk narzędzia, którym odwrócono leśną pieczęć.']],{requires:['win:root-warden']});
 fight('foreman-echo','miners-shift','Echo Ostatniego Sztygara','mine',15,190,[13,17]);
 inspect('mine-ledger','miners-shift','Zabezpiecz księgę ostatniej zmiany','mine','Na ostatniej stronie widnieją nazwiska górników, rozkaz zejścia do zamkniętego chodnika i niewielka kość owinięta kartą odprawy.',[['save','Zabierz odpis księgi i oznacz miejsce pamięci','Nazwiska oraz odbitka pieczęci zostały zabezpieczone.']],{requires:['win:foreman-echo']});
 inspect('bone-remembrance','bone-memory','Odczytaj pamięć kości','archive','Severin układa kość w kręgu mosiężnych znaków. Widzisz górników idących tunelem do bramy Cmentarzyska i urzędnika odsuwającego straż.',[['remember','Pozwól zmarłemu opowiedzieć własną historię','Pamięć została wysłuchana i zapisana.'],['bind','Utrwal odbicie wspomnienia w pieczęci','Odbicie wspomnienia zostało utrwalone, a kość złożona w szkatułce.']],{requires:['boss:1','visit:archive']});
 inspect('grave-register','sleepless-graves','Odczytaj rejestr Cmentarzyska','undercity','Za Minotaurem znajdujesz rejestr potajemnych pochówków. Zaginieni górnicy figurują pod datą wcześniejszą niż ich ostatnia zmiana.',[['copy','Porównaj rejestr z księgą górników','Fałszywe daty dowodzą, że los górników zaplanowano z wyprzedzeniem.']],{requires:['boss:5']});
 inspect('blade-imprint','blade-trace','Zbadaj ślad na ostrzu','mine','Kowal wskazuje nacięcie wykonane stemplem, nie dłutem. Na stali widać pęknięty siódmy pierścień, taki sam jak na glejtach transportowych.',[['trace','Wykonaj odcisk i śledź trasę kuriera','Kowal daje Ci porównanie nacięcia z królewskim wzorcem.']]);
 fight('seal-courier','blade-trace','Kurier Siódmej Pieczęci','undercity',22,240,[17,22],{requires:['blade-imprint'],enemy:{atlas:'tauriel',tile:2}});
 inspect('seal-comparison','masked-face','Porównaj trzy dowody','archive','Dokument Tauriel, księga górników i list kuriera leżą obok urzędowych wzorców. Każdy odcisk ma identyczną szczelinę w siódmym pierścieniu.',[['compare','Zestaw odciski z osobistym stemplem Severina','Tylko osobisty stempel Mistrza Pieczęci ma tę wadę.']],{requires:['visit:archive']});
 inspect('unmasked','masked-face','Zdejmij maskę kłamstwa','archive','Severin zaprzecza, dopóki nie pokazujesz mu szczeliny na jego własnym stemplu. „Przysięga chroniła tron, a nie ludzi” — mówi w końcu.',[['evidence','Przedstaw dowody i zażądaj wyjaśnień','Severin przyznaje się do zdrady. Odwrócił ochronne pieczęcie, by podporządkować sobie ich moc.']],{requires:['seal-comparison','visit:archive']});
 inspect('crown-warning','broken-crown','Ostrzeż królową','throne','Królowa wysłuchuje zeznań. Do ostatniego dzwonu pozostało niewiele czasu. Jej straż potrzebuje dowodu, by odciąć Severinowi drogę do komnaty rytuału.',[['warn','Przekaż komplet dowodów i zabezpiecz salę','Królowa zamyka przejścia. Pozostaje przerwać rytuał w Archiwum Pieczęci.']],{requires:['visit:throne']});
 fight('severin-oath','broken-crown','Severin — Pęknięta Przysięga','archive',25,290,[19,24],{requires:['crown-warning','visit:archive'],enemy:{atlas:'graveyard',tile:2}});
 inspect('trophy-memories','trophies','Opowiedz Tauriel o poległych','forest','Tauriel nie potrzebuje kolejnych kłów i czaszek. Pyta o ślady życia, które napotykasz na wyprawach: nazwiska, zgubione listy i ostatnie obietnice.',[['tell','Zapisz wspomnienia zamiast liczyć trofea','Księga Tauriel zachowa pamięć o ludziach, których wojna sprowadziła do liczb.']],{requires:['trophies:3']});
 inspect('ownerless-crate','ownerless-cargo','Zdecyduj o losie zaopatrzenia','mine','W skrzyni są bandaże, suche racje i oliwa. Fałszywa pieczęć zatarła właściciela, ale nic nie zmusza Cię, by oddać zapasy przemytnikom.',[['garrison','Przekaż zapasy straży Gabriela','Zapasy pomagają rannym obrońcom zamku.'],['healers','Oddaj skrzynię opiekunom górników','Rodziny zaginionej zmiany otrzymują potrzebne zaopatrzenie.']]);
 fight('mirror-shadow','lost-mirror','Cień Zaginionego Lustra','forest',15,175,[11,15],{enemy:{atlas:'graveyard',tile:0}});
 inspect('mirror-return','lost-mirror','Oddaj lustro Vesperze','vespera','W sypialni Vespery lustro nareszcie pokazuje właściwe odbicie. Na jego odwrocie dostrzegasz znak podobny do tych z królewskich glejtów.',[['return','Ustaw lustro w sypialni i opowiedz o cieniu','Vespera odzyskuje zgubę i zapisuje dla Ciebie wzór znaku.']],{requires:['win:mirror-shadow','visit:vespera-bedroom']});
 inspect('fallen-memorial','fallen-names','Przywróć poległym imiona','archive','W Archiwum Pieczęci porównujesz daty z kopalni i Cmentarzyska. Zamiast numerów możesz wreszcie zapisać pełne nazwiska.',[['names','Przepisz imiona na listę dla Gabriela','Żadne z odnalezionych imion nie zostaje pominięte.']],{requires:['boss:5','visit:archive']});
 inspect('outskirts-witness','outskirts-seal','Wysłuchaj świadka przy trakcie','ubocze','W karczmie „Pod Złotym Kucem” odnajdujesz woźnicę, który odmówił przyjęcia glejtu Severina. Pokazuje Ci polanę, gdzie zakopano pierwszą odwróconą pieczęć.',[['listen','Zapisz świadectwo i zabezpiecz znak','Znane jest położenie pieczęci Ubocza.']],{requires:['visit:ubocze']});
 fight('outskirts-warden','outskirts-seal','Strażnik Spalonego Traktu','forest',30,360,[25,30],{requires:['outskirts-witness']});
 inspect('eldor-song','eldor-seal','Odczytaj milczącą pieśń Eldoru','eldor','Elficka straż prowadzi Cię pod drzewo, którego liście zastygły w powietrzu. Ostatni wers pieśni zapisano od tyłu — tak samo jak krąg Severina.',[['song','Przywróć właściwy porządek pieśni','Pieśń otwiera drogę do uwięzionego opiekuna Eldoru.']],{requires:['visit:eldor']});
 fight('eldor-warden','eldor-seal','Uwięziony Opiekun Eldoru','eldor',50,600,[32,38],{requires:['eldor-song']});
 inspect('ice-runes','ice-seal','Odczytaj runy pod lodem','ice','Kronikarz krasnoludów wskazuje wyżłobienia starsze od królewskiej korony. Jedna runa płonie na czerwono, choć wokół niej zalega lód.',[['runes','Odczytaj runy zgodnie z kroniką','Znasz prawdziwe imię strażnika lodowej pieczęci.']],{requires:['visit:ice-hills']});
 fight('ice-warden','ice-seal','Strażnik Serca pod Lodem','ice',75,900,[35,45],{requires:['ice-runes']});
 inspect('hell-anchor','hell-seal','Odnajdź kotwicę rytuału','hell','Najemnicy wskazują skałę z siedmioma żelaznymi obręczami. Tędy moc pieczęci miała przepłynąć pod zamek. Pozostałe kręgi są już odwrócone z powrotem.',[['anchor','Połącz ślady czterech pieczęci','Kotwica zostaje odsłonięta. Ostatni strażnik wychodzi z popiołu.']],{requires:['visit:hell-gates']});
 fight('hell-warden','hell-seal','Strażnik Ostatniej Pieczęci','hell',110,1250,[40,55],{requires:['hell-anchor']});
 const ACTIVITIES=Object.freeze(acts.map(a=>Object.freeze(a)));
 const get=id=>CATALOG.find(q=>q.id===id),activity=id=>ACTIVITIES.find(a=>a.id===id);
 const PLACES=['archive','throne','vespera-bedroom','ubocze','eldor','ice-hills','hell-gates'];
 const empty=()=>({version:1,accepted:[],completed:[],clues:[],won:[],visits:[],decisions:{}});
 function read(h){
  const s=h.campaign;if(s===undefined)return empty();
  const list=(v,valid)=>Array.isArray(v)&&v.length<=60&&new Set(v).size===v.length&&v.every(x=>typeof x==='string'&&valid(x));
  if(!s||s.version!==1||!list(s.accepted,id=>!!get(id))||!list(s.completed,id=>s.accepted?.includes(id))||!list(s.clues,id=>activity(id)?.kind==='inspect'&&s.accepted.includes(activity(id).quest))||!list(s.won,id=>activity(id)?.kind==='fight'&&s.accepted.includes(activity(id).quest))||!list(s.visits,id=>PLACES.includes(id))||!s.decisions||typeof s.decisions!=='object'||Array.isArray(s.decisions))throw Error('Nieprawidłowy zapis kampanii. Zachowano pozostałe dane postaci.');
  if(s.accepted.some(id=>get(id).requires.some(previous=>!s.completed.includes(previous)))||Object.entries(s.decisions).some(([id,choice])=>!s.clues.includes(id)||!activity(id)?.choices?.some(c=>c.id===choice))||s.clues.some(id=>!Object.hasOwn(s.decisions,id)))throw Error('Niespójny postęp kampanii.');
  return s;
 }
 const done=(h,id)=>read(h).completed.includes(id);
 function condition(h,token){
  const s=read(h);
  if(token==='tauriel')return {done:h.taurielQuest?.status==='completed',label:'Ukończ zadanie Tauriel w karczmie',progress:`${h.taurielQuest?.defeated?.length||0} / 3 rozbójników`};
  if(token==='gabriel')return {done:window.GabrielTraining.unlocked(h),label:'Ukończ szkolenie Gabriela i oddaj uzbrojenie',progress:`${h.gabrielQuest?.recovered||0} / 3 części uzbrojenia`};
  if(token.startsWith('boss:')){const n=Number(token.split(':')[1]),count=window.Graveyard.count(h);return {done:count>=n,label:n===1?'Pokonaj pierwszego bossa Cmentarzyska':'Pokonaj wszystkich pięciu bossów Cmentarzyska',progress:`${Math.min(n,count)} / ${n}`};}
  if(token.startsWith('trophies:')){const legacy=(h.taurielQuest?.defeated?.length||0)+window.Graveyard.count(h),wins=Math.max(window.PlayerStats?.totals(h).wins||0,legacy);return{done:wins>=3,label:'Odnieś co najmniej trzy zwycięstwa',progress:`${Math.min(3,wins)} / 3`};}
  if(token.startsWith('visit:')){const id=token.slice(6),names={archive:'Archiwum Pieczęci',throne:'Sala tronowa','vespera-bedroom':'Sypialnia Vespery',ubocze:'Ubocze',eldor:'Eldor','ice-hills':'Lodowe Wzgórza','hell-gates':'Wrota Piekieł'};return{done:s.visits.includes(id),label:'Odwiedź: '+names[id],place:id};}
  const id=token.startsWith('win:')?token.slice(4):token,a=activity(id);if(!a)throw Error('Nieznany cel kampanii.');
  let complete=token.startsWith('win:')?s.won.includes(id):s.clues.includes(id);
  if(id.startsWith('report-')){const scene=id.slice(7);complete=complete||(h.playerStats?.missions?.[scene]||0)>0||(h.lastScout?.sceneId===scene&&h.lastScout.rewardClaimed===true);}
  return {done:!!complete,label:a.title,activity:id};
 }
 function status(h,id){const q=get(id);if(!q)throw Error('Nieznane zadanie kampanii.');const s=read(h),accepted=s.accepted.includes(id),completed=s.completed.includes(id),missing=q.requires.filter(id=>!s.completed.includes(id)),unlocked=window.Progression.level(h)>=q.level&&!missing.length,goals=q.goals.map(token=>condition(h,token));return{quest:q,accepted,completed,unlocked,missing,goals,ready:accepted&&!completed&&unlocked&&goals.every(g=>g.done)};}
 function idle(h){if(h.activeCombat||h.activeMission)throw Error('Najpierw zakończ obecną walkę lub zwiad.');}
 function accept(h,id){const p=status(h,id);if(p.accepted)return h;if(!p.unlocked)throw Error('Najpierw ukończ poprzedni etap i osiągnij wymagany poziom.');idle(h);const s=read(h);return{...h,campaign:{...s,accepted:[...s.accepted,id]}};}
 function usable(h,id){const a=activity(id);if(!a)throw Error('Nieznane spotkanie fabularne.');const p=status(h,a.quest);if(!p.accepted||p.completed||!p.unlocked)throw Error('Najpierw przyjmij właściwe zadanie w dzienniku.');if(a.requires.some(token=>!condition(h,token).done))throw Error('Najpierw zrealizuj wcześniejsze cele lub odwiedź wskazaną komnatę.');return a;}
 function gather(h,id,choice){idle(h);const a=usable(h,id),s=read(h);if(a.kind!=='inspect'||!a.choices.some(c=>c.id===choice))throw Error('Nieprawidłowa decyzja fabularna.');if(s.clues.includes(id))return h;return{...h,campaign:{...s,clues:[...s.clues,id],decisions:{...s.decisions,[id]:choice}}};}
 function begin(h,id,now=Date.now()){idle(h);const a=usable(h,id),s=read(h);if(a.kind!=='fight'||s.won.includes(id))throw Error('Ta walka została już ukończona.');return{...h,activeCombat:{id:crypto.randomUUID(),source:'campaign',campaignQuest:a.quest,campaignEncounter:id,cost:0,sceneId:a.scene,reward:{gold:0,xp:0},battle:window.BrandCombat.createBattle(window.BrandCombat.profile(h),a.enemy,'hero'),nextHitAt:now+1100}};}
 function resolve(h,id){const f=h.activeCombat,a=activity(f?.campaignEncounter),s=read(h);if(!f||f.id!==id||f.source!=='campaign'||!f.battle.winner||!a||a.kind!=='fight'||a.quest!==f.campaignQuest||f.battle.enemy.id!==a.enemy.id||s.won.includes(a.id)||!s.accepted.includes(a.quest)||s.completed.includes(a.quest))throw Error('Walka trwa albo została już rozliczona.');const won=f.battle.winner==='hero';return{...h,activeCombat:null,campaign:won?{...s,won:[...s.won,a.id]}:s,lastCampaignBattle:{id,encounter:a.id,won}};}
 function claim(h,id){idle(h);const p=status(h,id);if(!p.ready)throw Error(p.completed?'Nagroda za to zadanie została już odebrana.':'Najpierw ukończ wszystkie cele zadania.');const r=p.quest.reward,s=read(h);let next=window.Progression.award(h,r.xp);for(const key of ['gold','shards']){const base=h[key]??(key==='gold'?25:0);if(!Number.isSafeInteger(base)||base<0||!Number.isSafeInteger(base+r[key]))throw Error('Nieprawidłowy stan zasobów.');next={...next,[key]:base+r[key]};}next={...next,campaign:{...s,completed:[...s.completed,id]}};return window.PlayerStats?.recordMission(next,ACTIVITIES.find(a=>a.quest===id)?.scene||'other')??next;}
 function visit(h,place){if(!PLACES.includes(place))throw Error('Nieznana lokacja kampanii.');const s=read(h);if(s.visits.includes(place)||!s.accepted.some(id=>!s.completed.includes(id)&&(get(id).goals.includes('visit:'+place)||ACTIVITIES.some(a=>a.quest===id&&a.requires.includes('visit:'+place)))))return h;return{...h,campaign:{...s,visits:[...s.visits,place]}};}
 function validate(h){const s=read(h),f=h.activeCombat;if(f?.source==='campaign'){const a=activity(f.campaignEncounter);if(!a||a.kind!=='fight'||a.quest!==f.campaignQuest||!s.accepted.includes(a.quest)||s.completed.includes(a.quest)||s.won.includes(a.id)||f.battle?.enemy?.id!==a.enemy.id||f.sceneId!==a.scene||f.cost!==0||f.reward?.xp!==0||f.reward?.gold!==0)throw Error('Nieprawidłowy zapis walki fabularnej.');}return h;}
 const current=h=>CATALOG.find(q=>q.kind==='main'&&!done(h,q.id))||CATALOG.find(q=>q.kind==='chapter'&&!done(h,q.id));
 const encounterScene=f=>SCENES[activity(f?.campaignEncounter)?.scene]||SCENES.archive;
 window.OathCampaign={CATALOG,ACTIVITIES,SCENES,get,activity,read,done,condition,status,accept,gather,begin,resolve,claim,visit,validate,current,encounterScene};
})();
